        this.budget = budget;
        this.invoiced = invoiced;
        this.remaining = budget.subtract(invoiced);
    }

    public BigDecimal getBudget() {
        return budget;
    }

    public BigDecimal getInvoiced() {
        return invoiced;
    }

    public BigDecimal getRemaining() {
        return remaining;
    }
}

